import {
  BpmnValidateService
} from "./packager-tool-kg5sxneg.js";
import {
  VALID_PACKAGE_NAME_REGEX
} from "./packager-tool-eypvc2kv.js";
import"./packager-tool-jfv7t0c8.js";
import {
  NugetPackager,
  ensureProjectId
} from "./packager-tool-b803sdfp.js";
import"./packager-tool-nkrmjr3a.js";
import {
  catchError,
  logger,
  mapPackageMetadataOptions
} from "./packager-tool-79gws1zn.js";
import {
  getFileSystem
} from "./packager-tool-0v3s8r01.js";
import"./packager-tool-1yh8g550.js";

// src/services/maestro-pack-service.ts
var NUGET_VERSION_REGEX = /^(0|[1-9]\d*)\.(0|[1-9]\d*)(\.(0|[1-9]\d*))?(\.(0|[1-9]\d*))?(-[0-9A-Za-z][0-9A-Za-z-]*(\.[0-9A-Za-z][0-9A-Za-z-]*)*)?(\+[0-9A-Za-z][0-9A-Za-z-]*(\.[0-9A-Za-z][0-9A-Za-z-]*)*)?$/;
function isValidNugetVersion(version) {
  return NUGET_VERSION_REGEX.test(version);
}

class MaestroPackService {
  fs;
  constructor() {
    this.fs = getFileSystem();
  }
  async execute(projectPath, options) {
    const absoluteProjectPath = this.fs.path.resolve(projectPath);
    const absoluteOutputPath = this.fs.path.resolve(options.output);
    const packageName = options.name || this.fs.path.basename(projectPath);
    const version = options.version ?? "1.0.0";
    if (!VALID_PACKAGE_NAME_REGEX.test(packageName)) {
      throw new Error(`Invalid package name "${packageName}". Package name can only contain letters, numbers, dots (.), underscores (_), and hyphens (-).`);
    }
    if (!isValidNugetVersion(version)) {
      throw new Error(`Invalid package version "${version}". Package version must be a valid NuGet version, such as 1.0.0 or 1.0.0-beta.1.`);
    }
    logger.info(`
Packing Maestro project...
`);
    logger.info("Details:");
    logger.info(`  Project:  ${absoluteProjectPath}`);
    logger.info(`  Package:  ${packageName}@${version}`);
    logger.info(`  Output:   ${absoluteOutputPath}`);
    logger.info("");
    await this.validateProject(absoluteProjectPath);
    await ensureProjectId(absoluteProjectPath, this.fs);
    await this.fs.mkdir(absoluteOutputPath);
    let tempDir;
    try {
      tempDir = await this.fs.getTempDir();
      const stagingDir = this.fs.path.join(tempDir, "maestro-pack-staging");
      await this.fs.mkdir(stagingDir);
      const filesToCopy = [
        "operate.json",
        "entry-points.json",
        "bindings_v2.json",
        "package-descriptor.json"
      ];
      for (const file of filesToCopy) {
        const srcPath = this.fs.path.join(absoluteProjectPath, file);
        const destPath = this.fs.path.join(stagingDir, file);
        if (await this.fs.exists(srcPath)) {
          const content = await this.fs.readFile(srcPath);
          if (content) {
            await this.fs.writeFile(destPath, content);
          }
        }
      }
      const entries = await this.fs.readdir(absoluteProjectPath);
      for (const entry of entries) {
        if (entry.endsWith(".bpmn") || entry.endsWith(".xml")) {
          const srcPath = this.fs.path.join(absoluteProjectPath, entry);
          const destPath = this.fs.path.join(stagingDir, entry);
          const content = await this.fs.readFile(srcPath);
          if (content) {
            await this.fs.writeFile(destPath, content);
          }
        }
      }
      const packageId = `${packageName}.processOrchestration.ProcessOrchestration`;
      const nupkgPath = this.fs.path.join(absoluteOutputPath, `${packageId}.${version}.nupkg`);
      const packager = new NugetPackager(this.fs);
      const result = await packager.packAsync(stagingDir, {
        id: packageId,
        version,
        tags: "ProcessOrchestration",
        ...mapPackageMetadataOptions(options)
      }, nupkgPath);
      return {
        packageName: `${packageName}@${version}`,
        outputPath: result.outputPath
      };
    } finally {
      if (tempDir) {
        const [, exists] = await catchError(this.fs.exists(tempDir));
        if (exists) {
          await catchError(this.fs.rm(tempDir));
        }
      }
    }
  }
  async validateProject(projectPath) {
    if (!await this.fs.exists(projectPath)) {
      throw new Error(`Project path does not exist: ${projectPath}`);
    }
    const stats = await this.fs.stat(projectPath);
    if (!stats?.isDirectory()) {
      throw new Error(`Project path must be a directory: ${projectPath}`);
    }
    const descriptorPath = this.fs.path.join(projectPath, "package-descriptor.json");
    if (!await this.fs.exists(descriptorPath)) {
      throw new Error(`Missing package-descriptor.json in: ${projectPath}`);
    }
    await this.validateProjectJsonFile(descriptorPath, "package-descriptor.json");
    const operatePath = this.fs.path.join(projectPath, "operate.json");
    if (!await this.fs.exists(operatePath)) {
      throw new Error(`Missing operate.json in: ${projectPath}`);
    }
    await this.validateProjectJsonFile(operatePath, "operate.json");
    const entries = await this.fs.readdir(projectPath);
    if (entries.includes("entry-points.json")) {
      await this.validateProjectJsonFile(this.fs.path.join(projectPath, "entry-points.json"), "entry-points.json");
    }
    const bpmnFiles = entries.filter((entry) => entry.endsWith(".bpmn") || entry.endsWith(".xml"));
    if (bpmnFiles.length === 0) {
      throw new Error(`Missing BPMN file in: ${projectPath}`);
    }
    const validator = new BpmnValidateService(this.fs, {
      unsupportedExtensionTypeSeverity: "error"
    });
    for (const file of bpmnFiles) {
      const result = await validator.validateFile(this.fs.path.join(projectPath, file));
      if (!result.success) {
        const errors = result.issues.filter((issue) => issue.severity === "error");
        throw new Error(`BPMN validation failed for ${file}:
${errors.map((issue) => `  - [${issue.path}] ${issue.message}${issue.instruction ? ` ${issue.instruction}` : ""}`).join(`
`)}`);
      }
    }
  }
  async validateProjectJsonFile(filePath, fileName) {
    const content = await this.fs.readFile(filePath, "utf-8");
    if (!content) {
      throw new Error(`Invalid ${fileName}: file is empty.`);
    }
    const [parseErr, parsed] = catchError(() => JSON.parse(content));
    if (parseErr) {
      throw new Error(`Invalid ${fileName}: expected valid JSON. ${parseErr.message}`);
    }
    if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
      throw new Error(`Invalid ${fileName}: expected a JSON object.`);
    }
  }
}
export {
  MaestroPackService
};

